void UCharacterMovementComponent::ProcessLanded(const FHitResult& Hit, float remainingTime, int32 Iterations)
{
	SCOPE_CYCLE_COUNTER(STAT_CharProcessLanded);

	if( CharacterOwner && CharacterOwner->ShouldNotifyLanded(Hit) )
	{
		CharacterOwner->Landed(Hit);
	}
	if( IsFalling() )
	{
		if (GroundMovementMode == MOVE_NavWalking)
		{
			// verify navmesh projection and current floor
			// otherwise movement will be stuck in infinite loop:

		SetPostLandedPhysics(Hit);
	}

	IPathFollowingAgentInterface* PFAgent = GetPathFollowingAgent();
	if (PFAgent)
	{
		PFAgent->OnLanded();
	}

	StartNewPhysics(remainingTime, Iterations);
}

void UCharacterMovementComponent::SetPostLandedPhysics(const FHitResult& Hit)
{
	if( CharacterOwner )
	{
		if (CanEverSwim() && IsInWater())
		{
			SetMovementMode(MOVE_Swimming);
		}
		else
		{
			const FVector PreImpactAccel = Acceleration + (IsFalling() ? -GetGravityDirection() * GetGravityZ() : FVector::ZeroVector);
			const FVector PreImpactVelocity = Velocity;

			if (DefaultLandMovementMode == MOVE_Walking ||
				DefaultLandMovementMode == MOVE_NavWalking ||
				DefaultLandMovementMode == MOVE_Falling)
			{
				SetMovementMode(GroundMovementMode);
			}
			else
			{
				SetDefaultMovementMode();
			}

			ApplyImpactPhysicsForces(Hit, PreImpactAccel, PreImpactVelocity);
		}
	}
}

void UCharacterMovementComponent::ApplyImpactPhysicsForces(const FHitResult& Impact, const FVector& ImpactAcceleration, const FVector& ImpactVelocity)
{
	if (bEnablePhysicsInteraction && Impact.bBlockingHit )
	{
		if (UPrimitiveComponent* ImpactComponent = Impact.GetComponent())
		{
			FVector ForcePoint = Impact.ImpactPoint;
			float BodyMass = 1.0f; // set to 1 as this is used as a multiplier

			bool bCanBePushed = false;
			FBodyInstance* BI = ImpactComponent->GetBodyInstance(Impact.BoneName);
			if(BI != nullptr && BI->IsInstanceSimulatingPhysics())
			{
				BodyMass = FMath::Max(BI->GetBodyMass(), 1.0f);

				if(bPushForceUsingZOffset)
				{

				const FVector ComponentVelocity = ImpactComponent->GetPhysicsLinearVelocity(Impact.BoneName);
				const FVector VirtualVelocity = ImpactAcceleration.IsZero() ? ImpactVelocity : ImpactAcceleration.GetSafeNormal() * GetMaxSpeed();

				float Dot = 0.0f;

				if (bScalePushForceToVelocity && !ComponentVelocity.IsNearlyZero())
				{
					Dot = ComponentVelocity | VirtualVelocity;

					if (Dot > 0.0f && Dot < 1.0f)
					{
						PushForceModificator *= Dot;
					}
				}

				if (bPushForceScaledToMass)
				{
					PushForceModificator *= BodyMass;
				}
				const bool bClientAuthScheduledPushForces = CharacterMovementCVars::bEnableClientAuthScheduledPushForces && Chaos::FPhysicsSolverBase::IsNetworkPhysicsPredictionEnabled();

#if UE_WITH_REMOTE_OBJECT_HANDLE
				PushForceModificator *= PhysicsForceSubsteppingFactor;
#endif

				Force *= PushForceModificator;
				const float ZeroVelocityTolerance = 1.0f;
				if (ComponentVelocity.IsNearlyZero(ZeroVelocityTolerance))
				{
					Force *= InitialPushForceFactor;

					if (CharacterMovementCVars::bApplyCharacterCollisionForceAsImpulse)
					{
						if (!bClientAuthScheduledPushForces)
						{
							ImpactComponent->AddImpulseAtLocation(Force, ForcePoint, Impact.BoneName);
						}
						else
						{
							ApplyAsyncPhysicsStateAction(ImpactComponent, Impact.BoneName, EPhysicsStateAction::AddImpulseAtPosition, Force, ForcePoint);
						}
					}
					else
					{
						//Originally the force is applied as impulse, which was inaccurate. The extra scaling is applied so that the force is calibrated to match the old behavior at 30fps. 
						const float ExtraForceFactor = 30.f;
						Force *= ExtraForceFactor;

						if (!bClientAuthScheduledPushForces)
						{
							ImpactComponent->AddForceAtLocation(Force, ForcePoint, Impact.BoneName);
						}
						else
						{
							ApplyAsyncPhysicsStateAction(ImpactComponent, Impact.BoneName, EPhysicsStateAction::AddForceAtPosition, Force, ForcePoint);
						}
					}

void UCharacterMovementComponent::ApplyDownwardForce(float DeltaSeconds)
{
	if (StandingDownwardForceScale != 0.0f && CurrentFloor.HitResult.IsValidBlockingHit())
	{
		UPrimitiveComponent* BaseComp = CurrentFloor.HitResult.GetComponent();
		const FVector Gravity = -GetGravityDirection() * GetGravityZ();

		if (BaseComp && BaseComp->IsAnySimulatingPhysics() && !Gravity.IsZero())
		{
			BaseComp->AddForceAtLocation(Gravity * Mass * StandingDownwardForceScale, CurrentFloor.HitResult.ImpactPoint, CurrentFloor.HitResult.BoneName);
		}
	}
}

let travel = movement_sweep_travel(distance, hit.distance);
applied += *direction * travel;
let Some(normal) = hit.normal1.try_normalize() else { break };
contact |= normal.y > 0.0 && remaining.dot(normal) < 0.0;
remaining_time *= 1.0 - travel / distance;
if normal.y >= deg_to_rad(MAX_SLOPE_DEGREES).cos()
    && remaining.dot(normal) < 0.0
    && let Some(cmc) = landing_cmc {
    let extent = capsule.shape_scaled().compute_local_aabb().half_extents();
    let position = start + applied;
    if find_ground_floor(spatial, position, extent.y, extent.x.min(extent.z), cmc,
        LocomotionState::Air, &filter, entity, candidates)
        .is_some_and(|(center, impact, _)| (position.y - center).abs() <= MAX_FLOOR_DISTANCE
            && impact < position.y - extent.y + extent.x.min(extent.z)) {
        return (applied, velocity, contact, Some(remaining_time));
    }
}
let budget = velocity * remaining_time;
let slide = crate::extensions::motion::falling_slide(budget, normal, previous_normal);
previous_normal = Some(normal);
if remaining_time > f32::EPSILON { velocity = slide / remaining_time; }
if slide.dot(budget) <= 0.0 { break; }

let horizontal = crate::als::dynamics::grounded_velocity_step_with_braking_friction(
    velocity.with_y(0.0), desired_motion, max_speed,
    crate::als::params::GroundedDynamics { acceleration, braking_deceleration: 0.0, ground_friction: 0.0 },
    params.cmc.min_analog_walk_speed, 0.0, params.cmc.braking_substep_time, step);
velocity = crate::als::dynamics::clamp_falling_velocity(horizontal + Vec3::Y * velocity.y + gravity * step,
    gravity, terminal);
let requested = (old_velocity + velocity) * (0.5 * step);
let (applied, deflected, hit, landing_remaining) = falling_movement_sweep(spatial, capsule, transform.translation,
    transform.rotation, requested, velocity, step, Some(&params.cmc), entity, candidates);
transform.translation += applied;
contact |= hit;
let extent = capsule.shape_scaled().compute_local_aabb().half_extents();
if let Some(landing_remaining) = landing_remaining {
    remaining = remaining - step + landing_remaining;
    transitions.write(StateTransitionEvent { entity, dimension: Dimension::LocomotionState,
        from: StateValue::LocomotionState(LocomotionState::Air), to: StateValue::LocomotionState(LocomotionState::Grounded) });
    mode = LocomotionState::Grounded;
    adjust_walking_floor_height(spatial, capsule, &mut transform, extent.y, extent.x.min(extent.z),
        &params.cmc, entity, candidates);
    velocity.y = 0.0;
    if landing.1 {
        mode = LocomotionState::None;
        transitions.write(StateTransitionEvent { entity, dimension: Dimension::LocomotionState,
            from: StateValue::LocomotionState(LocomotionState::Grounded), to: StateValue::LocomotionState(mode) });
        break;
    }

if let Ok((mut base, dynamics)) = movement_bases.get_mut(entity) {
    if floor_entity.is_none() { floor_entity = validated_floor.map(|(_, _, entity)| entity); }
    base.entity = if *current == LocomotionState::Grounded { floor_entity } else { None };
    if let Some(entity) = base.entity && let Ok(global) = transforms.compute_global_transform(entity) {
